package handlers.skill.effects;

import java.util.Collection;

import org.l2jmobius.gameserver.entity.actor.Attackable;
import org.l2jmobius.gameserver.entity.actor.Creature;
import org.l2jmobius.gameserver.entity.actor.Player;
import org.l2jmobius.gameserver.entity.groups.Party;
import org.l2jmobius.gameserver.entity.item.enums.ItemProcessType;
import org.l2jmobius.gameserver.entity.item.holders.ItemHolder;
import org.l2jmobius.gameserver.entity.item.instance.Item;
import org.l2jmobius.gameserver.mechanics.effects.AbstractEffect;
import org.l2jmobius.gameserver.mechanics.skill.Skill;
import org.l2jmobius.gameserver.util.StatSet;

/**
 * This class handles the {@code Sweeper} effect implementation.<br>
 * It defines how the sweeper mechanic behaves within the game world.
 * @author Zoey76
 */
public class Sweeper extends AbstractEffect
{
	/**
	 * Creates a new instance of the {@code Sweeper} effect.<br>
	 * This constructor initializes the effect using the provided statistics.
	 * @param params The {@code StatSet} containing the configuration values.
	 */
	public Sweeper(StatSet params)
	{
	}
	
	/**
	 * Checks if the effect occurs instantly.<br>
	 * This method always returns {@code true}.
	 * @return {@code true} if the effect is instant.
	 */
	@Override
	public boolean isInstant()
	{
		return true;
	}
	
	/**
	 * Handles the immediate execution of a sweeping effect.<br>
	 * This method checks if the player can loot items from a monster.<br>
	 * It distributes the swept items to the player or their party.
	 * @param effector The {@code Creature} performing the action.
	 * @param effected The {@code Creature} being affected by the action.
	 * @param skill The {@code Skill} used to trigger the effect.
	 * @param item The {@code Item} associated with the effect.
	 */
	@Override
	public void instant(Creature effector, Creature effected, Skill skill, Item item)
	{
		if (!effector.isPlayer() || !effected.isAttackable())
		{
			return;
		}
		
		final Player player = effector.asPlayer();
		final Attackable monster = effected.asAttackable();
		if (!monster.checkSpoilOwner(player, false))
		{
			return;
		}
		
		if (!player.getInventory().checkInventorySlotsAndWeight(monster.getSpoilLootItems(), false, false))
		{
			return;
		}
		
		final Collection<ItemHolder> items = monster.takeSweep();
		if (items != null)
		{
			for (ItemHolder sweepedItem : items)
			{
				final Party party = player.getParty();
				if (party != null)
				{
					party.distributeItem(player, sweepedItem, true, monster);
				}
				else
				{
					player.addItem(ItemProcessType.SWEEP, sweepedItem, effected, true);
				}
			}
		}
	}
}
